export const COMBINING_IDEAS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Menggabungkan ide",q:"'Menggabungkan ide' berarti...",options:["Mengambil dua atau lebih ide & menyatukannya jadi satu ide baru yang lebih lengkap","Memilih satu ide paling disukai lalu membuang semua ide lain yang pernah disebut","Menyebut banyak ide satu per satu tanpa menghubungkan atau menyatukan satu pun"],answer:0,explain:"Banyak ide baru sebenarnya adalah gabungan ide lama: telepon + kamera + komputer = ponsel pintar.",hint:"Menyatukan jadi ide baru, atau memilih salah satu?"},
{n:2,type:"mcq",micro:"Membangun di atas ide",q:"'Membangun di atas ide teman' artinya...",options:["Mengulang ide teman persis seperti ucapannya tanpa menambah atau mengubah","Menerima idenya lalu menambahkan sesuatu yang membuatnya lebih baik","Mengganti ide teman dengan idemu karena menurutmu idemu lebih baik"],answer:1,explain:"'Ya, dan...' menambah lapisan. Ide sering jadi kuat setelah beberapa orang menambahkan bagiannya.",hint:"Menambah agar lebih baik, atau mengganti?"},
{n:3,type:"mcq",micro:"Contoh gabungan sehari-hari",q:"Manakah contoh benda yang lahir dari menggabungkan dua ide?",options:["Batu di halaman sekolah yang dipakai duduk","Air putih di gelas yang dibawa dari rumah","Penghapus di ujung pensil (pensil + penghapus)"],answer:2,explain:"Pensil dengan penghapus, kursi roda dengan meja lipat, sepatu dengan roda, semua gabungan dua fungsi.",hint:"Dua fungsi disatukan, atau satu benda biasa?"},
{n:4,type:"mcq",micro:"Mengembangkan ide",q:"'Mengembangkan' (mengelaborasi) sebuah ide berarti...",options:["Menambahkan detail: bagaimana cara kerjanya, untuk siapa, terbuat dari apa, seperti apa bentuknya","Menyebut idenya sekali lalu langsung pindah ke ide lain tanpa menjelaskan lagi kepada kelompok","Menghapus setengah bagian dari ide itu supaya terlihat lebih ringkas dan tidak makan tempat lagi"],answer:0,explain:"Ide mentah ('taman di atap') jadi berguna setelah dikembangkan: tanaman apa, siapa yang merawat, aman tidak.",hint:"Menambah detail konkret, atau menyebut sekali lalu pindah?"},
{n:5,type:"mcq",micro:"Menambah & mengurangi",q:"Dua cara sederhana mengubah sebuah ide jadi ide baru:",options:["Ganti semua bagiannya sekaligus sampai ide yang lama tidak tersisa sedikit pun di dalamnya","Tambahkan sesuatu (fitur, orang, langkah) atau kurangi sesuatu (buang bagian yang tidak perlu)","Ide hanya bisa dibiarkan apa adanya, sebab sebuah ide yang sudah jadi tidak mungkin diubah lagi"],answer:1,explain:"'Sepeda + motor kecil = sepeda listrik.' 'Telepon − kabel = telepon genggam.' Tambah/kurang menghasilkan ide baru.",hint:"Tambah atau kurangi bagian, atau biarkan apa adanya?"},
{n:6,type:"mcq",micro:"Membesarkan ide",q:"'Bagaimana kalau ide ini dibuat 10x lebih besar?' berguna untuk...",options:["Membuat ide jadi tidak masuk akal bagi pendengar lainnya","Tidak ada gunanya karena skala besar jarang dipakai orang","Melihat kemungkinan & masalah baru yang muncul di skala besar"],answer:2,explain:"Membesarkan 'perpustakaan mini kelas' jadi 'perpustakaan keliling antar-kelas' memunculkan ide & tantangan baru.",hint:"Memunculkan kemungkinan baru, atau membuat konyol?"},
{n:7,type:"mcq",micro:"Mengecilkan ide",q:"'Bagaimana versi paling kecil & sederhana dari ide ini?' membantu karena...",options:["Kita bisa mencobanya cepat & murah dulu sebelum membuat versi besar","Ide kecil lebih baik daripada ide besar, untuk masalah jenis apa saja","Membuat ide tak berarti lagi karena bagian pentingnya sudah dibuang dari awal"],answer:0,explain:"Versi kecil ('uji 1 rak buku dulu' bukan 'bangun perpustakaan') memberi pelajaran cepat dengan risiko kecil.",hint:"Bisa diuji cepat & murah, atau selalu lebih baik?"},
{n:8,type:"mcq",micro:"Ide + kebutuhan",q:"Cara menghubungkan ide dengan kebutuhan nyata:",options:["Cari kebutuhan nyatanya setelah idenya selesai dibuat, kalau-kalau ada yang perlu","Tanya 'masalah siapa yang ide ini pecahkan, & seberapa penting bagi mereka?'","Tak perlu dipikirkan, sebab ide bagus berguna bagi banyak orang tanpa dicek"],answer:1,explain:"Ide yang menempel pada kebutuhan nyata jadi bernilai. Ide tanpa kebutuhan jarang dipakai orang.",hint:"Hubungkan ke masalah nyata orang, atau anggap pasti berguna?"},
{n:9,type:"order",micro:"Dari dua ide ke satu",q:"Urutkan langkah menggabungkan dua ide jadi satu.",items:["Tuliskan dua ide secara terpisah & sebutkan bagian terbaik masing-masing","Bayangkan satu hal yang memakai bagian terbaik keduanya sekaligus","Kembangkan gabungan itu: cara kerja, untuk siapa, bahan","Periksa: apakah gabungan ini lebih baik dari kedua ide asli?"],answer:[0,1,2,3],explain:"Pisahkan & pahami → gabungkan bagian terbaik → kembangkan detail → bandingkan dengan asalnya.",hint:"Membandingkan hasil gabungan dilakukan di langkah pertama atau terakhir?"},
{n:10,type:"mcq",micro:"'Ya, dan' vs 'Ya, tapi'",q:"Saat mengembangkan ide bersama, kenapa 'Ya, dan...' lebih membantu dari 'Ya, tapi...'?",options:["Tidak ada bedanya karena keduanya sama-sama menanggapi ide teman","'Ya, tapi' lebih ramah karena terdengar sopan dan berhati-hati","'Ya, dan' menambah & menjaga ide tumbuh; 'Ya, tapi' menghentikannya"],answer:2,explain:"Fase mengembangkan butuh penambahan. Kritik ('ya, tapi') penting tapi ditaruh di fase menilai, bukan di sini.",hint:"Menambah & menumbuhkan, atau menghentikan?"},
{n:11,type:"tf",micro:"Ide baru sering gabungan lama",q:"Benar atau Salah: Banyak ide yang terasa 'baru' sebenarnya adalah gabungan dari ide-ide lama yang sudah ada.",answer:true,explain:"Kreativitas sering bukan menciptakan dari nol, melainkan menghubungkan hal-hal yang sebelumnya terpisah.",hint:"Gabungan ide lama, atau selalu dari nol?"},
{n:12,type:"tf",micro:"Menggabungkan = mencuri?",q:"Benar atau Salah: Menggabungkan ide dari dua orang teman dalam kelompok berarti mencuri ide mereka.",answer:false,explain:"Sebaliknya, dalam kerja kelompok menggabungkan ide adalah hal yang baik selama kontribusi tiap orang diakui. Yang tidak boleh adalah mengklaim ide orang sebagai milik sendiri.",hint:"Mencuri, atau kerja sama yang diakui?"},
{n:13,type:"mcq",micro:"Menambahkan indra",q:"Sebuah 'jam belajar' hanya menunjukkan waktu. Cara mengembangkannya dengan menambah indra:",options:["Tambahkan bunyi lembut atau lampu warna yang berubah saat waktunya istirahat","Buat jamnya lebih kecil supaya tak mencolok di meja siswa dan tak mengganggu","Hapus angkanya supaya siswa menebak sendiri kapan waktu istirahat tiba"],answer:0,explain:"Menambah cara ide 'berkomunikasi' (suara, cahaya, getaran) sering membuatnya lebih berguna.",hint:"Menambah cara menyampaikan info, atau memperkecil?"},
{n:14,type:"mcq",micro:"Menggabungkan dari bidang jauh",q:"Ide desain sering datang dari menggabungkan bidang yang jauh. Contohnya:",options:["Menghindari bidang lain supaya ide tetap murni","Cara duri menempel di baju → ide perekat (Velcro)","Menyalin persis desain yang sudah ada di pasaran"],answer:1,explain:"Menyilangkan 'alam' & 'produk', atau 'musik' & 'matematika', menghasilkan ide yang tidak muncul dari satu bidang saja.",hint:"Menyilangkan bidang jauh, atau menyalin yang ada?"},
{n:15,type:"mcq",micro:"Ide kurang kuat digabung",q:"Dua ide yang masing-masing 'biasa saja' bisa jadi ide kuat kalau...",options:["Keduanya tetap biasa saja karena saling menghilangkan pengaruh","Salah satu dibuang karena kelemahannya terlalu besar","Kelemahan satu ide ditutupi kekuatan ide lain saat digabung"],answer:2,explain:"'Lomba' (seru tapi ribut) + 'piket kebersihan' (perlu tapi malas) → 'lomba kelas terbersih' yang seru & berguna.",hint:"Saling menutup kelemahan, atau selalu tetap lemah?"},
{n:16,type:"tf",micro:"Mengembangkan butuh detail",q:"Benar atau Salah: Sebuah ide belum siap dicoba sampai dikembangkan dengan detail seperti langkah-langkahnya, siapa yang terlibat, & apa yang dibutuhkan.",answer:true,explain:"Ide satu kalimat sulit dikerjakan. Detail mengubah 'gagasan' jadi 'rencana' yang bisa dijalankan.",hint:"Perlu dikembangkan jadi detail, atau satu kalimat cukup?"},
{n:17,type:"mcq",micro:"Menambahkan 'untuk siapa lagi'",q:"Ide 'papan pengumuman kelas' bisa dikembangkan dengan bertanya...",options:["'Untuk siapa lagi ini berguna? Orang tua? Guru pengganti? Siswa yang absen?'","'Warnanya apa? Apakah ada pilihan warna lain yang lebih cerah dan ceria?'","'Siapa yang membuatnya dulu dan kapan pertama kali dipakai di sekolah lain?'"],answer:0,explain:"Menambah pengguna baru sering memperbesar nilai ide & memunculkan fitur baru (mis. versi foto untuk yang absen).",hint:"Memperluas pengguna, atau menanyakan detail kecil?"},
{n:18,type:"mcq",micro:"Menggabungkan langkah",q:"Dalam sebuah proses, menggabungkan dua langkah jadi satu berguna bila...",options:["Tidak berguna, sebab setiap langkah proses harus dikerjakan sendiri-sendiri oleh orang berbeda","Kedua langkah selalu dilakukan berurutan oleh orang yang sama — menyatukannya menghemat waktu","Semua langkah dalam proses harus digabung menjadi satu langkah besar demi menghemat waktu"],answer:1,explain:"Mis. 'mendata + memberi label' bisa jadi satu langkah. Tapi tidak semua langkah cocok digabung.",hint:"Bila selalu berurutan & satu orang, atau selalu digabung?"},
{n:19,type:"mcq",micro:"Ide + waktu",q:"Mengembangkan ide dengan dimensi waktu berarti bertanya...",options:["'Jam berapa sekarang? Apakah masih ada waktu cukup untuk mengerjakan ide ini hari ini?'","Tidak ada kaitan antara ide dengan waktu, sehingga pertanyaan seperti itu tidak perlu ditanyakan","'Apa yang terjadi sebelum, selama, & sesudah? Bagaimana ide ini dipakai hari pertama vs bulan keenam?'"],answer:2,explain:"Ide yang bagus di hari pertama bisa membosankan di bulan keenam. Memikirkan perjalanan waktunya memperkuat ide.",hint:"Memikirkan ide sepanjang waktu, atau tidak relevan?"},
{n:20,type:"open",micro:"Gabungkan & kembangkan",q:"Ambil dua ide ini: (1) 'kotak saran untuk kelas' dan (2) 'papan penghargaan siswa'. Gabungkan keduanya jadi satu ide baru, lalu kembangkan dengan minimal 5 detail (cara kerja, tempat, siapa mengelola, seberapa sering, apa yang membuatnya tetap menarik).",explain:"Jawaban baik: gabungan yang benar-benar menyatukan kedua ide (bukan sekadar menaruh berdampingan tanpa hubungan), plus minimal 5 detail konkret yang membuat ide bisa dijalankan & tetap hidup dari waktu ke waktu.",hint:"Pikirkan bagaimana kedua sisi saling menguatkan: saran yang ditindaklanjuti bisa jadi alasan penghargaan.",sample:"Ide gabungan: 'Papan Kelas Dua Sisi', satu sisi kotak saran & satu sisi penghargaan mingguan. Detail: (1) Cara kerja: siswa menulis saran di kertas & memasukkannya ke slot; tiap Jumat perwakilan kelas membaca saran & memilih satu untuk dibahas, lalu menempel nama siswa/kelompok yang membantu kelas minggu itu di sisi penghargaan. (2) Tempat: di dinding dekat pintu supaya terlihat semua orang setiap masuk & keluar. (3) Pengelola: tim bergilir 2 orang per minggu, dicatat di jadwal piket. (4) Seberapa sering: saran ditinjau seminggu sekali, penghargaan diperbarui seminggu sekali agar tidak basi. (5) Menjaga menarik: saran yang sudah ditindaklanjuti dipindah ke bagian 'sudah dikerjakan' dengan centang hijau, sehingga siswa melihat sarannya benar-benar berdampak; penghargaan menyebut alasan spesifik ('membantu merapikan rak', bukan hanya nama)."},
{n:21,type:"classify",micro:"Mengembangkan vs mengaburkan ide",q:"Kelompokkan tiap tindakan ke 'Mengembangkan ide' atau 'Mengaburkan ide'.",items:["Menambahkan detail cara kerja & untuk siapa","Menempelkan banyak fitur tak berhubungan sampai tujuannya hilang","Menguji versi kecilnya untuk melihat apa yang perlu diperbaiki","Terus mengubah arah ide setiap kali ada komentar"],groups:["Mengembangkan ide","Mengaburkan ide"],answer:{"Mengembangkan ide":["Menambahkan detail cara kerja & untuk siapa","Menguji versi kecilnya untuk melihat apa yang perlu diperbaiki"],"Mengaburkan ide":["Menempelkan banyak fitur tak berhubungan sampai tujuannya hilang","Terus mengubah arah ide setiap kali ada komentar"]},explain:"Mengembangkan = menambah kedalaman & kejelasan. Mengaburkan = menambah kerumitan sampai inti hilang.",hint:"Membuat ide lebih jelas & kuat, atau lebih kabur?"},
{n:22,type:"mcq",micro:"Sinergi",q:"'Sinergi' antara dua ide berarti...",options:["Gabungannya menghasilkan sesuatu yang lebih besar daripada menjumlahkan keduanya sendiri-sendiri","Keduanya saling membatalkan sehingga hasil gabungan lebih lemah daripada masing-masing ide tadi","Keduanya sama persis sehingga menggabungkannya tak menambah hal baru bagi proyek kelompok"],answer:0,explain:"1 + 1 = 3. 'Kelas menari' + 'pelajaran sejarah' → drama sejarah yang mengajari lebih dari keduanya terpisah.",hint:"Lebih besar dari jumlahnya, atau saling membatalkan?"},
{n:23,type:"mcq",micro:"PMI (Plus-Minus-Menarik)",q:"Teknik 'PMI' untuk menilai & mengembangkan ide berarti mendaftar...",options:["Hanya kekurangannya, karena kelebihan ide tak perlu dibahas lagi oleh kelompok yang menilai","Hal Positif, hal Negatif (Minus), & hal yang Menarik/perlu diselidiki lebih lanjut dari ide itu","Hanya hal positifnya, supaya penilaian terdengar menyenangkan dan tak menyakiti pembuat idenya"],answer:1,explain:"Kolom 'Menarik' penting: sering di situ letak benih pengembangan ('menarik, bagaimana kalau...').",hint:"Positif + Minus + Menarik, atau positif saja?"},
{n:24,type:"mcq",micro:"Mengembangkan lewat pertanyaan",q:"Pertanyaan yang mendorong pengembangan ide:",options:["'Apakah ini sudah selesai belum? Kalau sudah, kita bisa langsung pindah ke tugas berikutnya.'","'Siapa saja yang setuju dengan ide ini? Kalau banyak yang setuju, berarti idenya sudah matang.'","'Bagaimana persisnya ini bekerja? Apa yang bisa salah? Bagian mana yang paling penting?'"],answer:2,explain:"Pertanyaan 'bagaimana persisnya' & 'apa yang bisa salah' memaksa ide jadi konkret & lebih tahan uji.",hint:"Menggali cara kerja & risiko, atau menanyakan selesai/setuju?"},
{n:25,type:"mcq",micro:"Menggabungkan tanpa kehilangan tujuan",q:"Saat menggabungkan fitur dari banyak ide, yang harus dijaga:",options:["Tujuan utama tetap jelas — tiap fitur yang ditambah harus melayani tujuan itu, bukan sekadar 'keren'","Sebanyak mungkin fitur, karena tujuan tidak penting selama idenya terlihat lengkap dan canggih","Buang semua fitur tambahan supaya idenya kembali ke bentuk paling polos dan sederhana"],answer:0,explain:"Ide yang menumpuk fitur tanpa arah jadi berat & membingungkan. Tujuan adalah penyaringnya.",hint:"Fitur melayani tujuan, atau makin banyak makin baik?"},
{n:26,type:"mcq",micro:"Ide + ide dari orang berbeda",q:"Dalam kelompok, dua orang punya ide berbeda untuk masalah yang sama. Langkah kreatif sebelum memilih:",options:["Buang keduanya lalu cari ide ketiga dari nol supaya tak ada yang merasa kalah","Coba: 'Adakah cara memakai kekuatan kedua ide dalam satu solusi?'","Langsung voting untuk menentukan pemenang tanpa membahas isi kedua ide"],answer:1,explain:"Sering solusi terkuat adalah gabungan yang juga menyatukan kelompok, tidak ada yang merasa idenya 'kalah'.",hint:"Cari gabungan kekuatan keduanya, atau langsung voting?"},
{n:27,type:"tf",micro:"Semua ide bisa digabung?",q:"Benar atau Salah: Setiap dua ide selalu bisa & sebaiknya digabung menjadi satu.",answer:false,explain:"Sebaliknya, sebagian ide bertentangan atau punya tujuan berbeda; memaksakannya bersama menghasilkan solusi yang buruk di dua-duanya. Menggabungkan berguna hanya bila ada kecocokan.",hint:"Selalu gabung, atau hanya bila cocok?"},
{n:28,type:"tf",micro:"Elaborasi memperkuat",q:"Benar atau Salah: Meluangkan waktu mengembangkan detail sebuah ide sering mengungkap masalah tersembunyi sebelum kita terlanjur membuatnya.",answer:true,explain:"'Di langkah ini siapa yang bertanggung jawab?' bisa mengungkap celah yang, kalau diketahui belakangan, sudah mahal.",hint:"Mengungkap masalah lebih awal, atau buang waktu?"},
{n:29,type:"mcq",micro:"Menghindari 'ide Frankenstein'",q:"'Ide Frankenstein' adalah...",options:["Ide yang menakutkan karena terlalu banyak potongan seram digabung jadi satu di kelas","Ide yang sangat sederhana karena hanya terdiri dari satu bagian kecil yang jelas","Ide yang jadi jelek karena terlalu banyak potongan ide berbeda dijahit paksa tanpa kesatuan"],answer:2,explain:"Menggabungkan berlebihan tanpa arah menghasilkan sesuatu yang rumit, berat, & tidak jelas untuk apa.",hint:"Terlalu banyak potongan tanpa kesatuan, atau terlalu sederhana?"},
{n:30,type:"order",micro:"Mengembangkan ide terpilih",q:"Urutkan langkah mengembangkan satu ide terpilih.",items:["Tuliskan ide dalam satu kalimat & tujuannya","Rinci: siapa penggunanya, bagaimana cara kerjanya langkah demi langkah","Cari titik lemah: apa yang bisa gagal, bagian mana yang paling sulit","Perbaiki titik lemah itu atau tambahkan bagian yang menutupinya"],answer:[0,1,2,3],explain:"Perjelas inti → rinci cara kerja → temukan titik lemah → tambal. Pengembangan = memperdalam lalu memperkuat.",hint:"Mencari titik lemah sebelum atau sesudah merinci cara kerja?"},
{n:31,type:"mcq",micro:"Menambah nilai, bukan bobot",q:"Sebelum menambahkan fitur ke sebuah ide, pertanyaan penyaring yang baik:",options:["'Apakah ini membuat ide lebih berguna bagi pengguna, atau hanya membuatnya lebih rumit?'","'Apakah fitur tambahan ini terlihat canggih & keren di mata teman-teman serta guru kita?'","'Apakah temanku yang lain juga akan ikut menambahkan fitur yang sama pada ide mereka nanti?'"],answer:0,explain:"Setiap tambahan membawa biaya (waktu, kerumitan). Layak ditambah hanya bila nilainya melebihi biayanya.",hint:"Menambah kegunaan, atau menambah kerumitan demi terlihat canggih?"},
{n:32,type:"tf",micro:"Ide berkembang lewat umpan balik",q:"Benar atau Salah: Menunjukkan ide setengah jadi ke calon pengguna hanya membuang waktu; sebaiknya tunggu ide benar-benar selesai baru minta tanggapan.",answer:false,explain:"Sebaliknya, pengguna sering melihat kebutuhan & masalah yang tidak terpikir oleh pembuat ide. Umpan balik dini justru menghemat banyak usaha.",hint:"Umpan balik dini membantu, atau tunggu sampai jadi sempurna?"},
{n:33,type:"mcq",micro:"Menggabungkan bentuk & fungsi",q:"'Bangku taman yang juga jadi rak buku mini gratis' adalah gabungan...",options:["Satu fungsi yang diperbesar sehingga bangku menjadi jauh lebih panjang","Dua fungsi (tempat duduk + berbagi buku) dalam satu benda & tempat","Dua benda tak berhubungan yang hanya ditaruh berdampingan di tempat sama"],answer:1,explain:"Menyatukan dua fungsi yang cocok dalam satu tempat menghemat ruang & menciptakan kebiasaan baru (membaca sambil duduk).",hint:"Dua fungsi menyatu, atau tak berhubungan?"},
{n:34,type:"mcq",micro:"Kapan berhenti mengembangkan",q:"Sebuah ide sudah cukup dikembangkan untuk mulai diuji ketika...",options:["Setiap detail terkecilnya sudah sempurna dan tertulis rapi di atas kertas tanpa ada yang kurang","Sudah ditambahkan fitur sebanyak mungkin sehingga tidak ada lagi yang bisa ditambahkan ke dalamnya","Kamu bisa menjelaskan cara kerjanya ke orang lain & tahu langkah pertama untuk mencobanya"],answer:2,explain:"Menunggu 'sempurna di kertas' membuang waktu, uji nyata mengajari lebih cepat. Cukup jelas untuk dicoba = cukup.",hint:"Bisa dijelaskan & ada langkah pertama, atau sempurna di kertas?"},
{n:35,type:"mcq",micro:"Menyilangkan dua hobi",q:"Menggabungkan minat 'menggambar' & 'olahraga' bisa menghasilkan ide seperti...",options:["Buku panduan olahraga bergambar buatan siswa, atau papan skor yang dihias","Menggambar dan berolahraga tetap dilakukan di waktu berbeda tanpa hubungan","Berhenti melakukan keduanya supaya bisa fokus pada satu kegiatan saja"],answer:0,explain:"Menyilangkan dua hal yang kita sukai sering menghasilkan proyek yang lebih bersemangat kita kerjakan.",hint:"Ide yang menyatukan keduanya, atau dua kegiatan terpisah?"},
{n:36,type:"mcq",micro:"Ide dasar tetap terjaga",q:"Setelah banyak pengembangan, cara mengecek ide belum 'melenceng':",options:["Tambah lagi fitur-fitur baru sebanyak mungkin supaya idenya terlihat makin lengkap dan menarik","Kembali ke kalimat tujuan awal & tanya 'apakah versi sekarang masih melayani ini?'","Lupakan tujuan awal dulu, yang penting idenya sudah terlihat menarik bagi orang yang melihatnya"],answer:1,explain:"Tujuan awal adalah jangkar. Kalau pengembangan membuat ide tidak lagi melayani tujuan, ada yang perlu ditinjau.",hint:"Cek terhadap tujuan awal, atau lupakan tujuan?"},
{n:37,type:"tf",micro:"Pengembangan itu berulang",q:"Benar atau Salah: Mengembangkan ide biasanya berjalan sekali jadi, dari kasar langsung ke versi final tanpa perbaikan di tengah.",answer:false,explain:"Sebaliknya, ide berkembang melalui putaran: coba, lihat hasilnya, perbaiki, coba lagi. Versi final biasanya sangat berbeda dari draf pertama.",hint:"Sekali jadi, atau berputar & diperbaiki?"},
{n:38,type:"mcq",micro:"Menggabungkan solusi parsial",q:"Sebuah masalah besar punya 3 ide yang masing-masing hanya menyelesaikan sebagian. Sikap yang tepat:",options:["Pilih satu ide saja dan terima bahwa sisa masalahnya tak akan terpecahkan","Buang semuanya karena tak satu pun ide menyelesaikan seluruh masalah besar itu","Gabungkan ketiganya jadi satu rencana bertahap yang menutup seluruh masalah"],answer:2,explain:"Solusi lengkap sering merupakan gabungan beberapa solusi parsial yang saling melengkapi.",hint:"Gabungkan yang parsial jadi lengkap, atau pilih satu / buang semua?"},
{n:39,type:"mcq",micro:"Elaborasi visual",q:"Membuat sketsa atau model kasar dari ide gabungan berguna karena...",options:["Memaksa memikirkan bagaimana bagian-bagian benar-benar menyambung & sering memunculkan perbaikan","Membuang waktu, sebab ide bagus cukup dibayangkan di kepala tanpa digambar atau dibuat modelnya","Hanya berguna untuk ide-ide seni, sedangkan ide untuk masalah lain tak memerlukan sketsa sekolah"],answer:0,explain:"Di kepala, gabungan terasa mulus. Di sketsa, kita melihat 'bagian ini menabrak bagian itu' & bisa memperbaikinya.",hint:"Mengungkap sambungan yang bermasalah, atau buang waktu?"},
{n:40,type:"open",micro:"PMI sebuah ide gabungan",q:"Ide: 'Setiap kelas mengelola satu pojok tanaman di koridor sekolah, dan hasil panennya (mis. cabai, kemangi) dipakai untuk masakan di kantin.' Buat analisis PMI: minimal 3 hal Positif, 3 hal Minus, dan 3 hal Menarik. Lalu tulis satu perbaikan berdasarkan analisismu.",explain:"Jawaban baik: masing-masing minimal 3 poin yang benar-benar sesuai kolomnya (Minus adalah risiko/kekurangan nyata, bukan hal netral; Menarik adalah pertanyaan atau kemungkinan untuk digali, bukan pengulangan Positif), & satu perbaikan yang jelas menjawab salah satu Minus.",hint:"Kolom 'Menarik' harus berisi 'bagaimana kalau...' atau 'aku penasaran apakah...', bukan hal baik/buruk biasa.",sample:"Positif: (1) Siswa belajar merawat tanaman & tanggung jawab. (2) Koridor jadi lebih hijau & sejuk. (3) Kantin dapat bahan segar & bisa mengurangi biaya sedikit. Minus: (1) Butuh penyiraman rutin termasuk saat libur, siapa yang mengurus? (2) Tanaman bisa mati atau diserang hama & membuat siswa kecewa. (3) Panen mungkin terlalu sedikit untuk benar-benar dipakai kantin, jadi terasa sia-sia. Menarik: (1) Bagaimana kalau tiap kelas menanam jenis berbeda & saling menukar hasil? (2) Bagaimana kalau ada 'buku catatan tanaman' yang diwariskan ke kelas berikutnya tiap tahun? (3) Menarik untuk melihat apakah siswa yang ikut jadi lebih suka makan sayur. Perbaikan: buat jadwal piket penyiraman lintas kelas termasuk daftar 'penjaga libur', & mulai dengan tanaman yang tahan banting (kemangi, daun bawang) sebelum mencoba yang lebih sulit; kalau panen sedikit, pakai untuk satu menu khusus seminggu sekali, bukan diharapkan memenuhi kebutuhan harian."},
{n:41,type:"mcq",micro:"Matriks kombinasi",q:"'Matriks kombinasi': daftar pilihan untuk beberapa aspek (mis. tempat, waktu, bentuk kegiatan) dalam kolom, lalu...",options:["Coret semua kolom kecuali satu kolom saja supaya pilihan yang tersisa lebih sedikit dan lebih mudah","Pasangkan pilihan dari kolom berbeda secara sistematis atau acak untuk menemukan gabungan yang tak terpikir","Pilih satu pilihan dari kolom pertama saja lalu abaikan seluruh pilihan yang ada di kolom lainnya"],answer:1,explain:"Mis. tempat(aula/koridor/lapangan) × waktu(pagi/siang/sore) × bentuk(pameran/lomba/pertunjukan) = 27 gabungan untuk dipertimbangkan.",hint:"Pasangkan lintas kolom, atau pilih satu kolom saja?"},
{n:42,type:"mcq",micro:"Membangun berlapis",q:"Teknik 'ide inti + lapisan': mulai dari satu ide inti sederhana, lalu...",options:["Tambahkan semua lapisan perbaikan sekaligus di awal supaya idenya langsung lengkap","Jangan menambah apa-apa lagi pada ide inti setelah selesai dipikirkan pertama kali","Tambahkan satu lapisan perbaikan setiap kali, uji, baru tambah lapisan berikutnya"],answer:2,explain:"Menambah satu per satu & menguji membuat kita tahu lapisan mana yang benar-benar berguna & mana yang membebani.",hint:"Satu lapisan sekali lalu uji, atau semua sekaligus?"},
{n:43,type:"mcq",micro:"Menggabungkan lewat analogi",q:"'Bagaimana kalau perpustakaan bekerja seperti kafe?' adalah cara menggabungkan lewat...",options:["Analogi — meminjam cara kerja satu hal untuk mengembangkan hal lain","Menghapus perpustakaan dari rencana supaya kafe menjadi pengganti utamanya","Menghitung jumlah buku lalu membandingkannya dengan jumlah meja kafe"],answer:0,explain:"Dari 'seperti kafe': meja santai, colokan listrik, sudut ngobrol pelan, menu rekomendasi buku, semua ide pengembangan.",hint:"Meminjam cara kerja lewat analogi, atau menghitung?"},
{n:44,type:"mcq",micro:"Menambahkan 'mode'",q:"Sebuah ide 'aplikasi jadwal kelas' bisa dikembangkan dengan menambah mode:",options:["Menghapus jadwalnya supaya siswa tidak lagi bergantung pada informasi sekolah","Mode siswa, mode guru, mode orang tua — masing-masing melihat info yang relevan untuknya","Satu tampilan yang sama untuk semua, sekompleks mungkin agar terlihat lengkap"],answer:1,explain:"Memikirkan 'mode' atau 'peran' berbeda membuat satu ide melayani banyak pengguna tanpa membingungkan.",hint:"Tampilan sesuai peran, atau satu tampilan rumit untuk semua?"},
{n:45,type:"tf",micro:"Uji gabungan kecil dulu",q:"Benar atau Salah: Sebelum membuat versi lengkap dari ide gabungan yang rumit, sebaiknya uji dulu bagian paling berisiko atau paling tidak pasti dalam skala kecil.",answer:true,explain:"Menguji bagian yang paling meragukan lebih dulu memberi informasi terbanyak dengan usaha paling sedikit.",hint:"Uji bagian paling meragukan dulu, atau bangun semua langsung?"},
{n:46,type:"mcq",micro:"Menggabungkan dengan pembalikan",q:"Ide 'kelas mengajari kelas lain' bisa dikembangkan dengan pembalikan:",options:["Membalik semua meja di kelas supaya murid duduk menghadap ke arah yang berbeda dari biasanya","Tidak melakukan apa-apa dan membiarkan ide itu persis seperti awalnya, tanpa mengubah sedikit pun","'Bagaimana kalau kelas yang lebih muda yang mengajari kakak kelas sesuatu (mis. permainan, lagu daerah)?'"],answer:2,explain:"Membalik peran ('yang muda mengajar') memunculkan ide segar & sering lebih berkesan bagi kedua pihak.",hint:"Membalik peran untuk ide baru, atau membalik meja?"},
{n:47,type:"mcq",micro:"Menggabungkan solusi & pencegahan",q:"Untuk masalah 'buku hilang di perpustakaan', ide kuat sering menggabungkan...",options:["Solusi (cara menemukan buku yang hilang) + pencegahan (cara agar buku tidak mudah hilang)","Hanya menghukum murid yang menghilangkan buku supaya orang takut mengulanginya di kelas","Hanya membeli buku baru terus-menerus tiap ada buku hilang dari rak perpustakaan sekolah"],answer:0,explain:"Menangani masalah yang sudah terjadi & mencegah yang akan datang, sekaligus, biasanya lebih efektif daripada satu saja.",hint:"Solusi + pencegahan, atau menghukum saja?"},
{n:48,type:"mcq",micro:"Mengembangkan dari umpan balik",q:"Setelah menunjukkan ide ke 5 orang & mendapat komentar berbeda-beda, cara mengembangkan yang bijak:",options:["Abaikan semua komentar itu karena orang lain belum tentu mengerti maksud dan tujuan ideamu sebenarnya","Cari pola: masalah yang disebut banyak orang diprioritaskan; komentar tunggal dipertimbangkan tapi tidak selalu diikuti","Ubah ide mengikuti setiap komentar satu per satu sampai semua yang berkomentar merasa puas dan senang"],answer:1,explain:"Umpan balik diolah, bukan ditelan mentah. Pola keluhan berulang paling penting; selera pribadi satu orang kurang.",hint:"Cari pola & prioritaskan, atau ikuti setiap komentar / abaikan semua?"},
{n:49,type:"mcq",micro:"Menggabungkan sumber daya",q:"Dua kelompok punya proyek berbeda tapi kekurangan hal yang berbeda (satu kurang orang, satu kurang alat). Ide kolaboratif:",options:["Kedua kelompok menyerah saja karena masing-masing kekurangan sesuatu yang penting untuk proyeknya","Bersaing memperebutkan sumber daya sekolah yang terbatas supaya hanya kelompok terkuat yang berhasil","Gabungkan sebagian: kelompok A meminjamkan tenaga saat kelompok B butuh, B meminjamkan alat saat A butuh"],answer:2,explain:"Menggabungkan kekuatan yang saling melengkapi membuat dua proyek yang tadinya macet bisa jalan.",hint:"Saling meminjamkan yang berlebih, atau bersaing / menyerah?"},
{n:50,type:"order",micro:"Matriks kombinasi",q:"Urutkan langkah memakai matriks kombinasi untuk merancang acara kelas.",items:["Tentukan 3 aspek yang bisa bervariasi (mis. tempat, bentuk kegiatan, cara melibatkan penonton)","Tuliskan 3-4 pilihan untuk tiap aspek dalam kolom","Buat beberapa kombinasi dengan memasangkan pilihan lintas kolom","Pilih 2 kombinasi paling menarik & kembangkan detailnya"],answer:[0,1,2,3],explain:"Pilih aspek → isi pilihan → pasangkan → kembangkan yang terbaik. Matriks memaksa kita melihat gabungan yang biasanya terlewat.",hint:"Memasangkan lintas kolom sebelum atau sesudah menuliskan pilihan?"},
{n:51,type:"mcq",micro:"Menggabungkan lama & baru",q:"Ide 'perpustakaan digital' bisa diperkuat dengan menggabungkan hal dari perpustakaan lama:",options:["Pertahankan yang berhasil dari cara lama (rekomendasi personal, suasana tenang) & tambah kemudahan digital","Buang total semua kebiasaan lama perpustakaan karena cara yang baru lebih baik dalam segala hal yang ada","Tolak semua hal digital dan tetap pakai cara lama sepenuhnya tanpa perubahan karena cara lama sudah teruji"],answer:0,explain:"Menggabungkan 'yang terbaik dari lama' dengan 'yang terbaik dari baru' sering mengalahkan mengganti total.",hint:"Pertahankan yang berhasil + tambah yang baru, atau buang total salah satunya?"},
{n:52,type:"tf",micro:"Fitur inti vs tambahan",q:"Benar atau Salah: Saat mengembangkan ide, tidak ada gunanya memisahkan 'fitur inti' dari 'fitur tambahan'; semua sama pentingnya & harus dibuat bersamaan.",answer:false,explain:"Sebaliknya, memisahkan inti (tanpa ini ide tidak berfungsi) dari tambahan (bagus dimiliki, bisa menyusul) membantu kita membangun yang penting dulu & tidak tenggelam dalam hal yang bisa ditunda.",hint:"Pisahkan inti & tambahan, atau semua sama pentingnya?"},
{n:53,type:"mcq",micro:"Menggabungkan lewat 'dan juga'",q:"Mengembangkan ide 'papan info sekolah' dengan pola 'dan juga bisa...':",options:["Berhenti di ide papan info saja tanpa mengembangkannya karena ide itu sudah cukup bagus apa adanya","'...dan juga bisa jadi tempat menempel karya siswa', '...dan juga jadi kalender kegiatan', lalu pilih yang paling cocok","Menambahkan semua 'dan juga' yang terpikir tanpa memilih mana yang benar-benar cocok dengan tujuannya"],answer:1,explain:"'Dan juga bisa...' memunculkan banyak arah pengembangan; langkah berikutnya memilih yang paling melayani tujuan.",hint:"Munculkan banyak lalu pilih, atau tambahkan semua?"},
{n:54,type:"mcq",micro:"Prototipe gabungan",q:"Cara cepat menguji ide gabungan 'jam belajar dengan pengingat istirahat':",options:["Langsung rancang dan pesan alat elektronik khusus buatan pabrik lengkap dengan layar dan alarm, baru dicoba siswa","Hanya membayangkannya di kepala dengan sangat teliti selama seminggu tanpa mencoba versi kasarnya kepada orang lain mana pun","Buat versi kasar: timer HP biasa + kertas bertuliskan aturan istirahat, coba seminggu, catat apa yang membantu/mengganggu"],answer:2,explain:"Prototipe 'seadanya' menguji ide inti (ritme belajar-istirahat) tanpa biaya, sebelum membuat versi sungguhan.",hint:"Versi kasar seadanya dulu, atau langsung bikin alat khusus?"},
{n:55,type:"mcq",micro:"Menggabungkan umpan balik bertentangan",q:"Sebagian pengguna ingin ide 'lebih sederhana', sebagian ingin 'lebih banyak fitur'. Cara mengembangkan:",options:["Buat inti yang sederhana untuk semua, dengan fitur tambahan yang bisa dinyalakan bagi yang menginginkannya","Ikuti saja kelompok pengguna yang paling keras suaranya karena merekalah yang paling membutuhkannya","Buat dua versi terpisah yang berbeda dan tak punya bagian inti yang sama, sehingga tiap kelompok punya sendiri"],answer:0,explain:"'Sederhana secara bawaan, bisa diperdalam bila mau' sering memuaskan kedua kelompok tanpa membebani salah satu.",hint:"Inti sederhana + tambahan opsional, atau ikuti yang paling keras?"},
{n:56,type:"tf",micro:"Menggabungkan butuh penyaringan",q:"Benar atau Salah: Menggabungkan ide yang baik selalu diikuti langkah menyaring, memutuskan bagian mana yang benar-benar dipakai & bagian mana yang dibuang.",answer:true,explain:"Tanpa penyaringan, gabungan menumpuk jadi berat. Menggabungkan & memangkas adalah dua sisi dari satu proses.",hint:"Perlu disaring setelahnya, atau semua bagian dipakai?"},
{n:57,type:"mcq",micro:"Mengembangkan ide orang lain dengan hormat",q:"Temanmu punya ide bagus tapi belum lengkap. Cara mengembangkannya bersama:",options:["Diamkan saja sampai dia mengembangkannya sendiri karena ide itu adalah milik dia sepenuhnya, bukan kita","'Idemu bagus. Aku kepikiran menambah bagian ini, menurutmu bagaimana?' — mengajak, bukan mengambil alih","Ubah idenya langsung jadi versimu tanpa bertanya, karena menurutmu versimu lebih baik bagi kelompok"],answer:1,explain:"Mengembangkan ide orang lain paling baik dilakukan sebagai kolaborasi, dengan dia tetap merasa itu idenya.",hint:"Mengajak & bertanya, atau mengambil alih / mendiamkan?"},
{n:58,type:"mcq",micro:"Menggabungkan skala waktu",q:"Ide 'pengurangan sampah kelas' bisa dikembangkan dengan menggabungkan tindakan jangka pendek & panjang:",options:["Hanya membuat satu aturan besar yang baru bisa berjalan setelah persiapan selama setahun penuh lamanya","Hanya melakukan tindakan hari ini saja tanpa rencana lanjutan untuk minggu atau bulan berikutnya","Pendek: pisah sampah mulai besok. Panjang: kurangi sumber sampah lewat aturan bekal & kerja sama dengan kantin"],answer:2,explain:"Menggabungkan 'yang bisa dimulai sekarang' dengan 'yang mengubah akar masalah' membuat ide berdampak cepat & bertahan.",hint:"Pendek + panjang, atau hanya salah satu?"},
{n:59,type:"mcq",micro:"Menguji kesatuan ide",q:"Cara cepat mengecek apakah ide gabunganmu punya 'kesatuan':",options:["Coba jelaskan dalam satu kalimat — kalau butuh banyak 'dan juga... dan juga...', mungkin terlalu bercabang","Hitung jumlah fiturnya saja; kalau banyak, berarti idenya sudah lengkap dan terpadu dengan baik","Tanya teman apakah idenya terlihat rumit; kalau ia bilang tidak, berarti idenya sudah terpadu dengan baik"],answer:0,explain:"Ide yang menyatu bisa diringkas jadi satu kalimat jelas. Kalau tidak bisa, pertimbangkan memangkas.",hint:"Bisa diringkas satu kalimat, atau butuh banyak 'dan juga'?"},
{n:60,type:"open",micro:"Kembangkan sebuah gabungan",q:"Pilih dua kegiatan atau benda yang ada di sekolahmu. Gabungkan jadi satu ide, lalu kembangkan lewat 3 putaran: (putaran 1) versi paling sederhana, (putaran 2) tambahkan satu perbaikan berdasarkan kemungkinan masalah, (putaran 3) tambahkan satu cara agar tetap menarik setelah sebulan. Tulis ketiga putarannya.",explain:"Jawaban baik: gabungan yang jelas menyatukan dua hal, putaran 1 benar-benar versi paling sederhana yang bisa dijalankan, putaran 2 menyebut kemungkinan masalah nyata & perbaikannya, putaran 3 menambahkan mekanisme konkret untuk menjaga minat dari waktu ke waktu.",hint:"Putaran 1 harus terasa 'bisa mulai Senin ini'. Putaran 2 & 3 masing-masing menambah tepat satu hal.",sample:"Dua hal: 'mading (majalah dinding)' + 'sesi berbagi cerita antar kelas'. Ide gabungan: 'Mading Cerita', dinding tempat tiap kelas menempel satu cerita pendek atau pengalaman menarik per minggu, & sekali sebulan diadakan sesi membacakan cerita favorit. Putaran 1 (sederhana): satu papan di koridor, tiap kelas dapat satu kolom, isi cerita ditulis tangan di kertas A4, diganti tiap Senin. Putaran 2 (perbaikan atas kemungkinan masalah): masalah, cerita bisa jadi tidak pantas atau menyinggung; perbaikan, tiap cerita dicek dulu oleh satu guru pembina atau pengurus OSIS sebelum ditempel, & ada aturan singkat 'cerita menghibur atau menginspirasi, tidak menyindir orang tertentu'. Putaran 3 (agar tetap menarik): tiap bulan pilih 'cerita pilihan pembaca' lewat stiker yang ditempel siswa, cerita pilihan dibacakan di sesi bulanan & ditempel di bagian khusus 'Cerita Terbaik' yang menumpuk sepanjang tahun sehingga terlihat perjalanan kelas."},
{n:61,type:"mcq",micro:"Trade-off dalam menggabungkan",q:"Setiap kali menambahkan fitur dari ide lain, kita biasanya menukar...",options:["Kehilangan lebih banyak daripada yang didapat, sehingga menambah fitur tak pernah baik","Kesederhanaan & waktu pengerjaan demi kemampuan tambahan — perlu ditimbang apakah sepadan","Tak ada yang ditukar, kita hanya menambah kemampuan tanpa kehilangan apa-apa dari ide"],answer:1,explain:"Menyadari trade-off ('ini menambah 2 hari kerja untuk fitur yang dipakai 10% pengguna') membuat keputusan lebih jernih.",hint:"Menukar kesederhanaan/waktu, atau menambah tanpa biaya?"},
{n:62,type:"mcq",micro:"Terlalu banyak tujuan",q:"Ide yang mencoba melayani terlalu banyak tujuan sekaligus cenderung...",options:["Menjadi lebih baik karena ide lengkap melayani lebih banyak orang dengan baik sekali dalam waktu singkat","Menjadi lebih mudah dikerjakan karena banyaknya tujuan membuat tim punya lebih banyak pilihan jalan","Tidak melayani satu pun dengan baik — 'baik di banyak hal' sering berarti 'hebat di tidak satu pun'"],answer:2,explain:"Fokus adalah kekuatan. Lebih baik satu ide yang sangat berguna untuk satu hal daripada satu ide setengah berguna untuk lima hal.",hint:"Sulit unggul di satu pun, atau selalu lebih baik?"},
{n:63,type:"mcq",micro:"Memangkas dengan berani",q:"Saat mengembangkan, tanda sebuah fitur sebaiknya dipangkas:",options:["Kalau dihapus, tujuan utama ide tetap tercapai & sebagian besar pengguna tidak akan merasa kehilangan","Kalau fitur itu sulit dibuat oleh tim sehingga pengerjaannya terasa melelahkan dan memakan waktu","Kalau kamu sendiri yang mengusulkannya, supaya orang lain tidak merasa idemu lebih diutamakan"],answer:0,explain:"Uji pemangkasan: 'kalau ini hilang, apakah ide masih bekerja untuk tujuannya?' Kalau ya, pertimbangkan menghapusnya.",hint:"Tujuan tetap tercapai tanpanya, atau sekadar sulit dibuat?"},
{n:64,type:"tf",micro:"Menambah selalu lebih baik?",q:"Benar atau Salah: Ide yang lebih baik selalu adalah ide yang punya lebih banyak fitur & bagian.",answer:false,explain:"Sebaliknya, sering ide terbaik adalah yang paling sederhana yang masih menyelesaikan masalah. Menambah bagian menambah biaya, kerumitan, & titik yang bisa rusak.",hint:"Makin banyak fitur makin baik, atau sederhana yang cukup lebih kuat?"},
{n:65,type:"mcq",micro:"Menggabungkan yang bertentangan",q:"Dua ide punya nilai yang bertentangan (satu 'serba cepat', satu 'serba hati-hati'). Cara menyikapi:",options:["Buang keduanya lalu pilih tujuan lain yang lebih mudah dicapai oleh kelompok tanpa membahas kenapa bertentangan","Putuskan mana yang lebih penting untuk masalah ini, atau cari titik tengah yang jelas, jangan pura-pura keduanya bisa maksimal","Gabung saja dan berharap keduanya tercapai penuh, karena kelompok yang baik mampu melakukan semuanya sekaligus di waktu yang sama"],answer:1,explain:"Nilai yang bertentangan butuh pilihan sadar atau kompromi yang jelas, bukan gabungan yang menyembunyikan konflik.",hint:"Pilih prioritas / titik tengah jelas, atau berharap keduanya penuh?"},
{n:66,type:"mcq",micro:"Biaya kerumitan",q:"Kenapa ide yang rumit lebih berisiko gagal saat dijalankan?",options:["Kerumitan tak berpengaruh pada keberhasilan, yang penting idenya terdengar menarik bagi pendengar, dan banyak orang suka","Ide yang rumit lebih dihargai orang sehingga kemungkinan gagalnya justru lebih kecil, terutama di depan guru yang menilai","Lebih banyak bagian = lebih banyak yang bisa salah, lebih sulit dijelaskan ke orang lain, & lebih lama dikerjakan"],answer:2,explain:"Setiap bagian tambahan adalah titik kegagalan potensial & beban pemahaman. Kesederhanaan membuat ide lebih tangguh.",hint:"Lebih banyak titik gagal & beban, atau tidak berpengaruh?"},
{n:67,type:"mcq",micro:"Mengembangkan vs menunda meluncurkan",q:"'Kita kembangkan sedikit lagi sebelum dicoba' bisa jadi jebakan bila...",options:["Dipakai terus-menerus untuk menghindari menghadapi umpan balik nyata dari pengguna","Dilakukan hanya sekali untuk memperbaiki cacat yang sudah jelas terlihat dan mudah diperbaiki","Ada tenggat yang mendesak sehingga waktu pengembangan memang harus dipersingkat oleh seluruh tim"],answer:0,explain:"Pada titik tertentu, pengembangan lebih lanjut di kepala kalah berguna dibanding satu uji nyata. Kenali kapan harus berhenti & mencoba.",hint:"Menghindari umpan balik nyata, atau memperbaiki cacat jelas sekali?"},
{n:68,type:"mcq",micro:"Menjaga penulis ide tetap terlibat",q:"Saat mengembangkan ide bersama, penting menjaga...",options:["Tidak ada seorang pun yang boleh menyentuh atau mengubah ide asli sampai proyeknya benar-benar selesai","Orang yang pertama mengusulkan tetap merasa memiliki & dilibatkan dalam keputusan pengembangan","Ide sepenuhnya diambil alih oleh anggota yang paling vokal & paling sering berbicara di dalam kelompok"],answer:1,explain:"Ide yang dikembangkan bersama-sama, dengan penggagas tetap dihormati, menghasilkan komitmen lebih kuat untuk mengerjakannya.",hint:"Penggagas tetap dilibatkan, atau diambil alih?"},
{n:69,type:"mcq",micro:"Menguji apakah gabungan perlu",q:"Sebelum menggabungkan dua ide, pertanyaan yang jujur:",options:["'Apakah kedua ide ini kebetulan dibuat oleh orang-orang yang paling kusukai di dalam kelompok?'","'Apakah gabungan ini akan terlihat lebih pintar & lebih mengesankan di depan guru dan teman-teman?'","'Apakah gabungan ini benar-benar lebih baik untuk pengguna, atau aku hanya tidak mau memilih di antara keduanya?'"],answer:2,explain:"Kadang menggabungkan adalah cara menghindari keputusan sulit. Gabungan yang baik menambah nilai, bukan menunda pilihan.",hint:"Benar-benar lebih baik, atau menghindari memilih?"},
{n:70,type:"tf",micro:"Kesatuan mengalahkan kelengkapan",q:"Benar atau Salah: Ide yang menyatu & jelas untuk satu tujuan biasanya lebih berhasil daripada ide yang mencoba lengkap tapi kehilangan fokus.",answer:true,explain:"Pengguna & pengerja sama-sama butuh kejelasan. Ide yang bisa dijelaskan dalam satu kalimat lebih mudah dipahami, dikerjakan, & dipakai.",hint:"Menyatu & fokus, atau lengkap tapi kabur?"},
{n:71,type:"mcq",micro:"Menggabungkan bertahap",q:"Cara aman menggabungkan banyak ide ke satu proyek besar:",options:["Mulai dengan gabungan inti terkecil yang berfungsi, jalankan, lalu tambahkan ide berikutnya bila terbukti perlu","Gabungkan semua ide ke dalam rencana awal sebelum mengerjakan apa-apa supaya tak ada yang tertinggal di kelompok","Kerjakan setiap ide sebagai proyek terpisah dan jangan menyatukannya, bagaimanapun hasilnya nanti di kelas"],answer:0,explain:"'Inti dulu, tambah bertahap' memungkinkan belajar dari kenyataan sebelum menambah kerumitan.",hint:"Inti dulu lalu tambah bertahap, atau semua di awal?"},
{n:72,type:"mcq",micro:"Ide yang tidak jadi digabung",q:"Ide bagus yang akhirnya tidak masuk ke gabungan final sebaiknya...",options:["Dipaksa masuk saja ke dalam gabungan demi menghargai pengusulnya walau tidak cocok dengan tujuan","Disimpan dengan catatan alasannya — mungkin cocok untuk proyek atau versi berikutnya","Dibuang begitu saja & tidak boleh disebut lagi supaya kelompok tidak terpecah oleh ide yang tersingkir"],answer:1,explain:"Bank ide adalah aset. Memaksakan ide masuk hanya demi perasaan justru merusak kesatuan proyek.",hint:"Simpan untuk nanti, atau buang / paksa masuk?"},
{n:73,type:"mcq",micro:"Umpan balik saat pengembangan lanjut",q:"Semakin jauh ide dikembangkan, kita cenderung...",options:["Makin mudah menerima kritik karena kita paham seluruh isi dan seluk-beluk ide kita itu","Tidak terpengaruh oleh seberapa banyak waktu dan tenaga yang sudah kita curahkan pada ide","Makin sulit menerima kritik karena sudah banyak berinvestasi — perlu sadar & tetap terbuka"],answer:2,explain:"'Terlalu sayang untuk diubah' adalah jebakan. Semakin dalam kita masuk, semakin penting sengaja mengundang pandangan luar.",hint:"Makin sulit terima kritik, atau makin mudah?"},
{n:74,type:"mcq",micro:"Menilai gabungan dengan kriteria",q:"Cara adil membandingkan beberapa versi gabungan ide:",options:["Nilai tiap versi terhadap kriteria yang sama (mis. kegunaan, kemudahan dibuat, biaya, daya tahan)","Pilih versi yang paling banyak fiturnya karena itu yang paling berguna bagi pengguna nanti","Pilih versi yang paling baru diusulkan karena itu yang paling segar dan paling dekat di ingatan kita"],answer:0,explain:"Kriteria yang konsisten membuat perbandingan objektif & keputusan bisa dijelaskan ke semua anggota.",hint:"Bandingkan dengan kriteria sama, atau hitung fitur?"},
{n:75,type:"order",micro:"Menyederhanakan ide yang terlalu rumit",q:"Ide gabungan kelompokmu jadi terlalu rumit. Urutkan langkah menyederhanakannya.",items:["Tuliskan ulang tujuan utama ide dalam satu kalimat","Daftar semua bagian/fitur yang saat ini ada","Tandai bagian yang tanpanya tujuan utama masih tercapai","Pangkas bagian yang ditandai (simpan catatannya untuk nanti)"],answer:[0,1,2,3],explain:"Perjelas tujuan → daftar bagian → tandai yang tidak esensial → pangkas. Tujuan adalah alat ukur mana yang boleh hilang.",hint:"Menandai bagian yang bisa dihapus sebelum atau sesudah memperjelas tujuan?"},
{n:76,type:"tf",micro:"Menggabungkan itu keterampilan",q:"Benar atau Salah: Kemampuan menggabungkan ide dengan baik adalah bakat tetap yang tidak berubah meski dilatih.",answer:false,explain:"Sebaliknya, seperti keterampilan lain, makin sering kita menggabungkan & melihat hasilnya (berhasil atau gagal), makin baik penilaian kita tentang mana yang cocok disatukan & mana yang harus dipilih.",hint:"Meningkat dengan latihan, atau bakat tetap?"},
{n:77,type:"mcq",micro:"Menggabungkan ide dengan kenyataan",q:"Bagian penting mengembangkan ide adalah menabrakkannya dengan kenyataan:",options:["Kecilkan ide sampai tak berarti lagi supaya bisa dikerjakan dengan sumber daya yang ada","Cek sumber daya, waktu, aturan, & kemampuan tim yang benar-benar ada, lalu sesuaikan ide","Abaikan semua keterbatasan yang ada, memeriksanya cukup dilakukan nanti saja setelah ide sudah selesai"],answer:1,explain:"Ide yang dikembangkan tanpa memeriksa kenyataan sering runtuh saat dijalankan. Menyesuaikan lebih awal lebih murah.",hint:"Cek & sesuaikan dengan kenyataan, atau abaikan keterbatasan?"},
{n:78,type:"mcq",micro:"Kapan gabungan lebih buruk",q:"Menggabungkan dua ide menghasilkan hasil LEBIH BURUK daripada memilih satu ketika...",options:["Kedua ide saling melengkapi sehingga setiap kekurangan salah satunya ditutup oleh kelebihan yang lain","Salah satu ide jelas lebih lemah tetapi tetap dimasukkan supaya pengusulnya tidak merasa kecewa nanti","Kedua ide butuh perhatian penuh & saling menarik ke arah berlawanan sehingga keduanya jadi setengah matang"],answer:2,explain:"Gabungan yang memaksa dua tujuan yang bertarik menghasilkan kompromi yang tidak memuaskan siapa pun.",hint:"Saling menarik berlawanan, atau saling melengkapi?"},
{n:79,type:"mcq",micro:"Peran 'penjaga kesederhanaan'",q:"Dalam kelompok yang cenderung terus menambah fitur, berguna ada orang yang...",options:["Secara berkala bertanya 'apakah kita masih fokus? bagian mana yang bisa kita hapus?'","Menyetujui tambahan apa saja dari anggota lain supaya suasana kelompok tetap menyenangkan","Menolak semua ide sejak awal supaya proyek tetap kecil dan tak perlu ditambah lagi"],answer:0,explain:"'Penjaga kesederhanaan' menyeimbangkan dorongan alami kelompok untuk menumpuk, menjaga ide tetap bisa dikerjakan.",hint:"Menjaga fokus & memangkas, atau setuju menambah apa pun?"},
{n:80,type:"open",micro:"Trade-off nyata",q:"Sebuah kelompok mengembangkan ide 'aplikasi bank sampah sekolah'. Awalnya sederhana (catat setoran, hitung poin). Sekarang mereka ingin menambah: peta lokasi sampah, papan peringkat antar kelas, fitur chat, & artikel edukasi. Untuk tiap tambahan, tulis: apa nilainya, apa biayanya (waktu/kerumitan), & putusan kamu (masuk sekarang / nanti / tidak usah) beserta alasan.",explain:"Jawaban baik: tiap tambahan dianalisis dengan tiga hal (nilai, biaya, putusan+alasan), putusan konsisten dengan analisisnya, & ada prinsip pemilihan yang jelas (mengutamakan nilai tinggi + biaya rendah + dekat tujuan inti). Tidak semua tambahan diterima.",hint:"Bandingkan tiap fitur pada dua sumbu: seberapa besar mendukung tujuan inti, & seberapa mahal/rumit membuatnya.",sample:"1. Peta lokasi sampah: Nilai, memudahkan siswa tahu ke mana membawa sampah, mengurangi kebingungan. Biaya, sedang, perlu data lokasi & tampilan peta yang jelas di HP. Putusan, NANTI, berguna tapi masalah 'bingung lokasi' bisa dulu diatasi dengan poster fisik. 2. Papan peringkat antar kelas: Nilai, memotivasi lewat persaingan sehat, bisa menaikkan partisipasi banyak. Biaya, kecil, datanya sudah ada dari poin, tinggal ditampilkan berurutan. Putusan, MASUK SEKARANG, biaya rendah & mendukung tujuan inti (lebih banyak setoran). 3. Fitur chat: Nilai, kecil untuk tujuan bank sampah; siswa sudah punya cara lain berkomunikasi. Biaya, tinggi, perlu pengawasan agar tidak disalahgunakan. Putusan, TIDAK USAH, biaya jauh melebihi nilainya & menambah risiko. 4. Artikel edukasi: Nilai, sedang, membantu siswa paham kenapa memilah penting. Biaya, kecil sampai sedang, bisa mulai dengan 3-4 artikel pendek. Putusan, NANTI, tambahkan setelah fitur inti stabil, mulai dari satu artikel di halaman utama. Prinsip yang kupakai, dahulukan tambahan yang biayanya kecil & langsung mendukung tujuan inti (lebih banyak sampah terpilah), tunda yang berguna tapi bisa digantikan cara sederhana, tolak yang biayanya besar & jauh dari tujuan."},
{n:81,type:"mcq",micro:"Skenario: dua kelompok, satu acara",q:"Dua kelompok merancang acara yang mirip & guru meminta mereka menggabungkan. Langkah pertama yang baik:",options:["Bagi acara menjadi dua bagian terpisah sehingga tiap kelompok mengerjakan bagiannya sendiri tanpa bertemu atau berdiskusi satu sama lain","Masing-masing menyebut 2 bagian terbaik idenya, lalu bersama merancang satu acara yang memakai bagian-bagian itu di sekitar satu tujuan","Pilih ide milik salah satu kelompok saja & buang yang lain sepenuhnya supaya tidak ada perdebatan panjang, lalu kelompok satunya cukup membantu"],answer:1,explain:"Menggabungkan yang adil dimulai dari mengenali kekuatan tiap sisi, lalu membangun kesatuan baru di sekitar tujuan bersama.",hint:"Ambil bagian terbaik keduanya di sekitar satu tujuan, atau pilih satu / pecah dua?"},
{n:82,type:"mcq",micro:"Skenario: ide membengkak",q:"Proyek kelasmu dimulai sebagai 'pojok baca' & kini punya 12 fitur. Tenggat 2 minggu lagi. Yang harus dilakukan:",options:["Kerjakan semua 12 fitur itu lebih cepat, bahkan jika harus mengurangi waktu istirahat anggota","Ganti proyek jadi sesuatu yang lain supaya anggota bisa mulai lagi dari awal yang baru","Kembali ke tujuan inti, pilih 3-4 fitur yang paling melayaninya & bisa selesai, tunda sisanya"],answer:2,explain:"Saat waktu sempit & ide membengkak, memangkas ke inti yang bisa selesai dengan baik adalah keputusan dewasa.",hint:"Pangkas ke inti yang bisa selesai, atau kejar semua?"},
{n:83,type:"mcq",micro:"Skenario: gabungan terasa hambar",q:"Ide gabungan kelompokmu 'aman' tapi tidak ada yang bersemangat. Cara menghidupkannya:",options:["Cari satu bagian yang berani/tidak biasa dari salah satu ide asli & masukkan kembali, meski sedikit berisiko","Terima saja ide itu apa adanya karena sudah disepakati bersama dan tidak perlu diubah lagi nanti","Tambah lebih banyak fitur yang aman & biasa saja supaya idenya terlihat lebih lengkap dan meyakinkan"],answer:0,explain:"Menggabungkan sampai semua sudut tajam hilang menghasilkan ide hambar. Satu elemen berani sering mengembalikan energinya.",hint:"Kembalikan satu elemen berani, atau terima yang hambar?"},
{n:84,type:"mcq",micro:"Skenario: fitur favorit harus dipangkas",q:"Fitur yang kamu usulkan & sukai ternyata harus dipangkas demi tenggat. Sikap yang baik:",options:["Diam-diam tetap mengerjakan fitur itu di luar jam kelompok supaya tak ada yang tahu dan melarang","Terima demi keberhasilan proyek, catat idenya untuk versi berikutnya, & bantu fokus ke inti","Menolak keputusan itu dan mengancam berhenti membantu kalau fiturmu dipangkas dari proyek"],answer:1,explain:"Keberhasilan proyek bersama lebih penting daripada satu fitur favorit. Ide yang dipangkas hari ini bisa kembali nanti.",hint:"Terima & simpan untuk nanti, atau menolak / diam-diam kerjakan?"},
{n:85,type:"tf",micro:"Gabungan terbaik sering sederhana",q:"Benar atau Salah: Gabungan ide yang paling berhasil sering justru menggabungkan sedikit hal dengan sangat pas, bukan banyak hal sekaligus.",answer:true,explain:"Menyatukan 2-3 hal yang benar-benar saling menguatkan biasanya mengalahkan menjahit 8 hal yang setengah cocok.",hint:"Sedikit tapi pas, atau sebanyak mungkin?"},
{n:86,type:"mcq",micro:"Skenario: ide bagus dari luar kelompok",q:"Kelompok lain menawarkan ide yang bisa memperkuat proyekmu. Sikap terbuka:",options:["Tolak saja tawaran itu karena idenya bukan berasal dari kelompokmu sendiri dan belum tentu cocok","Ambil idenya begitu saja tanpa menyebut dari mana asalnya supaya terlihat seperti ide kelompokmu sendiri","Pertimbangkan dengan serius, akui kontribusinya, & lihat apakah cocok dengan tujuan proyek"],answer:2,explain:"Ide bagus tidak mengenal batas kelompok. Menerima & mengakui membangun hubungan baik sekaligus memperkuat proyek.",hint:"Pertimbangkan & akui, atau tolak / ambil diam-diam?"},
{n:87,type:"mcq",micro:"Skenario: menggabungkan gaya berbeda",q:"Dalam proyek seni kelompok, tiap orang punya gaya berbeda. Cara menggabungkan:",options:["Cari 'benang merah' (tema, warna, atau format) yang menyatukan sambil membiarkan tiap bagian punya ciri khas pembuatnya","Paksa semua anggota meniru satu gaya yang sama persis dengan gaya anggota yang paling pandai menggambar supaya hasilnya rapi","Biarkan tiap bagian dikerjakan sendiri-sendiri dengan tema, warna, dan ukuran bebas, tanpa hubungan satu sama lain"],answer:0,explain:"Kesatuan tidak berarti keseragaman. Benang merah yang jelas membuat karya terasa satu tanpa menghapus keragaman.",hint:"Benang merah + ciri khas masing-masing, atau seragam / tak berhubungan?"},
{n:88,type:"mcq",micro:"Skenario: pengguna bingung",q:"Saat menguji ide gabungan, pengguna berkata 'aku tidak mengerti ini untuk apa'. Artinya:",options:["Idenya sudah bagus, jadi abaikan saja komentar itu karena pengguna belum mengerti manfaatnya","Kemungkinan idenya terlalu bercabang atau tujuannya tidak terkomunikasikan, perlu diperjelas atau dipangkas","Penggunanya yang kurang pintar sehingga tidak perlu repot-repot menjelaskan atau mengubah idenya"],answer:1,explain:"Kalau tujuan tidak langsung terasa oleh pengguna, itu masalah ide, bukan masalah pengguna. Perjelas inti atau sederhanakan.",hint:"Ide perlu diperjelas/dipangkas, atau salahkan pengguna?"},
{n:89,type:"mcq",micro:"Skenario: menggabungkan proyek yang gagal",q:"Dua proyek kelas gagal tahun lalu. Sebelum menggabungkan bagian-bagiannya jadi proyek baru:",options:["Anggap gabungan itu akan berhasil karena idenya baru dan berbeda dari dua proyek yang lama dulu","Ulangi persis kedua proyek itu sekaligus dalam satu rencana besar dengan harapan hasilnya berbeda","Pelajari kenapa masing-masing gagal, ambil hanya bagian yang tidak menjadi penyebab kegagalan"],answer:2,explain:"Menggabungkan bagian yang gagal tanpa memahami sebabnya hanya menggabungkan kegagalan. Belajar dulu, baru gabungkan yang sehat.",hint:"Pelajari sebab gagal & ambil bagian sehat, atau anggap pasti berhasil?"},
{n:90,type:"order",micro:"Proyek: kembangkan ide gabungan",q:"Urutkan langkah proyek mingguan 'gabungkan & kembangkan satu ide'.",items:["Hari 1: pilih 2-3 ide, sebutkan kekuatan tiap ide, susun satu gabungan inti","Hari 2: kembangkan detail gabungan & cari titik lemahnya","Hari 3-4: buat prototipe kasar & uji ke beberapa calon pengguna","Hari 5: pangkas bagian yang tidak berguna, perkuat inti, siapkan versi untuk dipakai"],answer:[0,1,2,3],explain:"Gabung inti → kembangkan & temukan lemah → prototipe & uji → pangkas & perkuat. Uji nyata datang sebelum menyelesaikan.",hint:"Memangkas & memperkuat di awal atau setelah menguji?"},
{n:91,type:"mcq",micro:"Skenario: menggabungkan atas tekanan waktu",q:"Waktu tinggal sedikit & ada godaan menggabungkan semua sisa ide 'sekalian'. Sikap yang tepat:",options:["Tahan godaan itu; gabungkan hanya yang jelas menguatkan inti & bisa selesai baik, sisanya untuk lain waktu","Gabungkan semua ide yang tersisa sekalian supaya tidak ada anggota yang merasa idenya terbuang percuma","Berhenti mengerjakan proyek karena waktunya sudah terlalu sedikit untuk menyelesaikan apa-apa lagi di sekolah"],answer:0,explain:"Tekanan waktu adalah alasan untuk lebih memilih, bukan kurang. Menggabungkan asal-asalan di akhir biasanya merusak.",hint:"Gabungkan yang menguatkan inti & bisa selesai, atau semua sekalian?"},
{n:92,type:"tf",micro:"Ide asal tetap dihargai",q:"Benar atau Salah: Setelah ide digabung, tidak perlu lagi mengakui ide atau orang yang menjadi bahannya; gabungan itu milik yang menyatukan.",answer:false,explain:"Sebaliknya, mengakui ide-ide & orang yang jadi bahan gabungan menjaga kepercayaan & semangat kerja sama. Orang yang idenya diakui akan terus berkontribusi.",hint:"Akui bahan & orangnya, atau anggap gabungan milik yang menyatukan?"},
{n:93,type:"mcq",micro:"Skenario: gabungan menemui jalan buntu",q:"Gabungan ide kelompok mentok, dua bagian tidak bisa disatukan secara teknis. Langkah kreatif:",options:["Batalkan seluruh proyek itu karena bagian yang tidak bisa disatukan berarti idenya memang tidak layak","Curah gagasan cara ketiga untuk mencapai tujuan yang sama, atau pilih satu bagian & lepaskan yang lain dengan sadar","Paksakan saja menyatukan kedua bagian itu walaupun hasilnya tidak berfungsi dengan baik, asal selesai tepat waktu"],answer:1,explain:"Jalan buntu pada satu gabungan bukan akhir. Kembali ke tujuan & cari rute lain, atau buat pilihan yang jelas.",hint:"Cari rute ketiga / pilih dengan sadar, atau paksa / batalkan?"},
{n:94,type:"mcq",micro:"Skenario: mengembangkan ide sederhana yang berhasil",q:"Ide sederhana kelompokmu berhasil di uji kecil. Godaannya menambah banyak fitur untuk versi besar. Sikap bijak:",options:["Tambahkan fitur sebanyak mungkin selagi anggota bersemangat sehingga versi besarnya lengkap dan menarik perhatian guru","Biarkan persis sama seperti versi kecil tanpa perbaikan walaupun pengguna sudah memberi masukan, agar tidak membingungkan pengguna","Tambahkan hanya fitur yang diminta pengguna saat uji & yang mendukung tujuan; jaga kesederhanaan yang membuatnya berhasil"],answer:2,explain:"Yang membuat ide berhasil sering justru kesederhanaannya. Kembangkan berdasarkan bukti dari pengguna, bukan dorongan menambah.",hint:"Tambah berdasar permintaan pengguna & tujuan, atau sebanyak mungkin?"},
{n:95,type:"tf",micro:"Menggabungkan & memilih keduanya perlu",q:"Benar atau Salah: Dalam proses kreatif yang sehat, kita bergantian antara menggabungkan/menambah ide & memilih/memangkas, keduanya dibutuhkan.",answer:true,explain:"Menambah tanpa memangkas menghasilkan kekacauan; memangkas tanpa menambah menghasilkan kemiskinan ide. Iramanya bergantian.",hint:"Butuh keduanya bergantian, atau cukup satu?"},
{n:96,type:"mcq",micro:"Skenario: ide gabungan untuk masalah nyata",q:"Masalah: siswa baru sering tersesat & kesepian di minggu pertama. Kamu punya ide 'peta sekolah' & ide 'kakak asuh'. Gabungan yang kuat:",options:["'Kakak asuh' yang tugas pertamanya mengajak keliling sambil memberi peta beranotasi buatan siswa, lalu menemani makan siang minggu pertama","Bagikan peta sekolah kepada siswa baru tanpa kakak asuh yang mendampingi, lalu berharap mereka menemukan jalan sendiri dengan mudah","Tunjuk kakak asuh begitu saja tanpa panduan tentang hal yang harus dilakukan, sehingga tiap kakak asuh bebas berbuat sesukanya untuk adiknya"],answer:0,explain:"Menggabungkan 'informasi' (peta) dengan 'hubungan manusia' (kakak asuh) menutup dua kebutuhan sekaligus, lebih kuat dari salah satunya.",hint:"Gabungkan informasi + pendampingan dengan tugas jelas, atau salah satu saja?"},
{n:97,type:"mcq",micro:"Menilai apakah pengembangan sudah cukup",q:"Ide siap dijalankan (bukan dikembangkan lagi) ketika...",options:["Tak ada lagi ide tambahan yang bisa dibayangkan oleh anggota kelompok, sekecil apa saja ide itu, jadi proyek dianggap siap dikerjakan","Tujuan jelas, cara kerja bisa dijelaskan, titik lemah utama sudah ditutup, & langkah pertama + penanggung jawab sudah ada","Setiap kemungkinan yang bisa terjadi sudah dipikirkan sampai tuntas & tidak ada lagi yang tersisa sedikit pun"],answer:1,explain:"Kesiapan bukan kesempurnaan. Cukup jelas + titik lemah utama tertutup + ada langkah & orang = mulai, sisanya diperbaiki sambil jalan.",hint:"Cukup jelas & siap dimulai, atau semua kemungkinan terpikir?"},
{n:98,type:"mcq",micro:"Menggabungkan ide antar mata pelajaran",q:"Proyek yang menggabungkan matematika & seni, atau sains & bahasa, sering...",options:["Membingungkan siswa dan sebaiknya dihindari supaya setiap pelajaran tetap terpisah rapi dari awal sampai akhir","Hanya cocok untuk sebagian kecil siswa yang berbakat sehingga tidak perlu dicoba oleh semua murid","Membuat kedua pelajaran terasa lebih hidup & menunjukkan bagaimana pengetahuan saling terhubung di dunia nyata"],answer:2,explain:"Di dunia nyata, masalah jarang datang dalam satu 'mata pelajaran'. Proyek lintas bidang melatih menghubungkan pengetahuan.",hint:"Membuat pelajaran lebih hidup & terhubung, atau selalu membingungkan?"},
{n:99,type:"mcq",micro:"Prinsip inti menggabungkan",q:"Prinsip paling penting saat menggabungkan & mengembangkan ide:",options:["Setiap bagian yang disatukan atau ditambahkan harus melayani satu tujuan yang jelas — kesatuan mengalahkan kelengkapan","Semakin banyak ide digabung menjadi satu, semakin baik hasilnya, apa saja tujuan proyeknya nanti, karena lengkap itu penting","Gabungkan ide dari anggota yang paling berpengaruh di kelompok agar proyek mudah diterima oleh guru dan teman"],answer:0,explain:"Tujuan yang jelas adalah penyaring & perekat. Ia menentukan apa yang masuk, apa yang keluar, & apa yang membuat gabungan terasa 'satu'.",hint:"Semua melayani satu tujuan jelas, atau makin banyak makin baik?"},
{n:100,type:"open",micro:"Kapstone: gabungkan, kembangkan, sederhanakan",q:"Pilih satu masalah nyata. Kumpulkan minimal 3 ide untuk masalah itu (boleh dari curah gagasanmu sendiri). Lalu: (a) gabungkan bagian terbaiknya jadi satu ide dengan tujuan yang jelas dalam satu kalimat, (b) kembangkan lewat minimal 5 detail cara kerja, (c) sebutkan 2 kemungkinan masalah & cara menutupnya, (d) sederhanakan: sebutkan satu bagian yang akan kamu pangkas untuk versi pertama & alasannya, (e) tulis langkah pertama & siapa yang akan mengerjakannya.",explain:"Jawaban baik: minimal 3 ide awal, gabungan dengan tujuan satu kalimat yang jelas, minimal 5 detail cara kerja yang konkret, 2 masalah nyata + penutupnya, satu pemangkasan sadar dengan alasan (menunjukkan kemampuan menyederhanakan), & langkah pertama yang spesifik dengan penanggung jawab.",hint:"Bagian (d) menguji apakah kamu berani memangkas, pilih bagian yang paling rumit atau paling tidak siap, bukan yang paling penting.",sample:"Masalah: banyak makanan bekal terbuang di kelas karena anak lupa membawa atau tidak suka menu di rumah. Tiga ide: (1) 'meja berbagi' tempat menaruh makanan utuh yang tidak dimakan, (2) survei menu supaya orang tua tahu yang disukai, (3) 'teman bekal' berpasangan agar saling mengingatkan membawa bekal. (a) Ide gabungan & tujuan: 'Pojok Bekal Kelas', sistem sederhana agar lebih sedikit bekal terbuang & tidak ada anak yang tidak makan siang. (b) Detail: 1) Ada rak kecil 'berbagi' untuk makanan kemasan utuh yang tidak jadi dimakan, diambil oleh yang mau, diperiksa guru piket agar layak. 2) Pasangan 'teman bekal' saling pesan singkat pagi hari 'sudah bawa bekal?'. 3) Sekali sebulan kelas mengisi daftar '3 menu bekal favorit' yang disalin & dikirim ke grup orang tua. 4) Sisa makanan basah yang tidak habis dikumpulkan di satu wadah untuk kompos tanaman kelas. 5) Papan kecil mencatat 'berapa hari minggu ini tidak ada bekal terbuang' sebagai pengingat bersama. (c) Kemungkinan masalah: (i) makanan di rak berbagi bisa basi/tidak higienis, ditutup dengan aturan 'hanya kemasan tertutup & utuh, dibuang sore hari kalau tidak diambil', diawasi piket. (ii) 'teman bekal' bisa jadi saling menyalahkan kalau lupa, ditutup dengan membingkainya sebagai saling membantu, bukan mengawasi, & pasangan diganti tiap bulan. (d) Pangkas untuk versi pertama: fitur kompos (nomor 4) ditunda, karena butuh wadah, jadwal, & tempat tanaman yang belum siap; fokus dulu ke mengurangi bekal terbuang. (e) Langkah pertama: minggu ini aku & satu teman menyiapkan rak berbagi + menempel aturannya, & membuat daftar pasangan 'teman bekal' untuk disepakati di kelas hari Senin."},
];
